#!/usr/bin/env python3
"""Snapshot Noctalia settings.toml to a self-contained, Git-tracked config.nix."""

import datetime as dt
import math
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import time
import tomllib

MARKER = "# Generated by noctalia-settings-export (Home Manager watcher)"
OLD_MARKER = "# Noctalia settings, mirrored from the GUI by the dmopp/settings-to-nix plugin"

HEADER = """# Generated by noctalia-settings-export (Home Manager watcher)
# Snapshot of Noctalia's GUI settings. Do not edit: the next export replaces it.
# To restore manually: $(nix-build --no-out-link ./config.nix)/bin/noctalia-restore-settings
{ pkgs ? import <nixpkgs> { } }:
let
  settings = """

FOOTER = r""";
  settingsToml = (pkgs.formats.toml { }).generate "noctalia-settings.toml" settings;
in
(pkgs.writeShellScriptBin "noctalia-restore-settings" ''
  set -eu
  PATH=${pkgs.coreutils}/bin:$PATH
  umask 077
  if [ -n "''${NOCTALIA_STATE_HOME:-}" ]; then
    dir="$NOCTALIA_STATE_HOME/noctalia"
  elif [ -n "''${XDG_STATE_HOME:-}" ]; then
    dir="$XDG_STATE_HOME/noctalia"
  else
    dir="$HOME/.local/state/noctalia"
  fi
  mkdir -p "$dir"
  if [ -e "$dir/settings.toml" ]; then
    cp "$dir/settings.toml" "$dir/settings.toml.bak-$(date +%Y%m%d-%H%M%S)"
  fi
  tmp=$(mktemp "$dir/.settings.toml.XXXXXX")
  cp ${settingsToml} "$tmp"
  chmod 600 "$tmp"
  mv -f "$tmp" "$dir/settings.toml"
  touch "$dir/.setup-complete"
  echo "Noctalia settings restored. Restart Noctalia to activate plugins."
'') // { inherit settings; }
"""


def nix_string(s: str) -> str:
    # JSON and Nix double-quoted strings share these common escapes.
    if any(ord(ch) < 32 and ch not in "\n\r\t" for ch in s):
        raise ValueError("Unsupported control character in Noctalia setting")
    escaped = (
        s.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("${", r"\${")
        .replace("\n", r"\n")
        .replace("\r", r"\r")
        .replace("\t", r"\t")
    )
    return '"' + escaped + '"'


def nix_value(v, depth=0, in_list=False):
    ind = "  " * depth
    next_ind = "  " * (depth + 1)
    if isinstance(v, dict):
        if not v:
            return "{ }"
        lines = ["{"]
        for k in sorted(v):
            lines.append(f"{next_ind}{nix_string(k)} = {nix_value(v[k], depth + 1)};")
        lines.append(ind + "}")
        return "\n".join(lines)
    if isinstance(v, list):
        if not v:
            return "[ ]"
        lines = ["["]
        lines.extend(f"{next_ind}{nix_value(item, depth + 1, True)}" for item in v)
        lines.append(ind + "]")
        return "\n".join(lines)
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        result = str(v)
        return f"({result})" if in_list and v < 0 else result
    if isinstance(v, float):
        if not math.isfinite(v):
            raise ValueError("Cannot export non-finite TOML float to Nix")
        result = repr(v)
        if "e" in result and "." not in result:
            result = result.replace("e", ".0e", 1)
        return f"({result})" if in_list and result.startswith("-") else result
    if isinstance(v, (dt.datetime, dt.date, dt.time)):
        return nix_string(v.isoformat())
    if isinstance(v, str):
        return nix_string(v)
    raise TypeError(f"Unsupported setting type: {type(v).__name__}")


def exclude_volatile_wallpaper_paths(settings):
    wallpaper = settings.get("wallpaper")
    if not isinstance(wallpaper, dict):
        return
    for key in ("last", "default"):
        entry = wallpaper.get(key)
        if isinstance(entry, dict):
            entry.pop("path", None)
    monitors = wallpaper.get("monitors")
    if isinstance(monitors, dict):
        for entry in monitors.values():
            if isinstance(entry, dict):
                entry.pop("path", None)


def main(source: Path, target: Path):
    if not source.is_file():
        raise FileNotFoundError(f"Noctalia settings missing: {source}")
    if not target.parent.is_dir():
        raise FileNotFoundError(f"Target directory missing: {target.parent}")
    if target.is_symlink():
        raise RuntimeError(f"Refusing to overwrite symlink: {target}")

    old = target.read_text(encoding="utf-8") if target.exists() else None
    if old is not None and not (old.startswith(MARKER) or old.startswith(OLD_MARKER)):
        raise RuntimeError(f"Refusing to replace unmanaged file: {target}")

    # A brief debounce allows Noctalia to finish a burst of GUI writes.
    time.sleep(0.3)
    data = source.read_bytes()
    settings = tomllib.loads(data.decode("utf-8"))
    exclude_volatile_wallpaper_paths(settings)
    content = HEADER + nix_value(settings, 1) + FOOTER
    if content == old:
        return

    # Never modify config.nix unless the replacement parses successfully.
    fd, name = tempfile.mkstemp(prefix=".noctalia-config-", suffix=".nix", dir=target.parent)
    tmp = Path(name)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        os.chmod(tmp, 0o600)
        subprocess.run(["nix-instantiate", "--parse", str(tmp)], check=True,
                       stdout=subprocess.DEVNULL)
        if source.read_bytes() != data:
            raise RuntimeError("settings.toml changed during export; retry after saving")
        if target.is_symlink():
            raise RuntimeError(f"Target became a symlink: {target}")
        os.replace(tmp, target)
        print(f"Updated {target}")
    finally:
        tmp.unlink(missing_ok=True)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("Usage: export-settings.py SETTINGS_TOML CONFIG_NIX")
    try:
        main(Path(sys.argv[1]).expanduser(), Path(sys.argv[2]).expanduser())
    except Exception as exc:
        sys.exit(f"Noctalia export failed: {exc}")
